from django.db import models
class Contract(models.Model):
    position=models.ForeignKey('engine_trading.Position',on_delete=models.CASCADE,related_name='contracts')
    contract_id=models.CharField(max_length=120,db_index=True); proposal_id=models.CharField(max_length=120,blank=True); contract_type=models.CharField(max_length=40); duration=models.PositiveIntegerField(default=1); duration_unit=models.CharField(max_length=12,default='m'); barrier=models.CharField(max_length=40,blank=True); buy_price=models.DecimalField(max_digits=18,decimal_places=8,default=0); sell_price=models.DecimalField(max_digits=18,decimal_places=8,null=True,blank=True); payout=models.DecimalField(max_digits=18,decimal_places=8,default=0); settlement=models.DecimalField(max_digits=18,decimal_places=8,null=True,blank=True); profit=models.DecimalField(max_digits=18,decimal_places=8,default=0); status=models.CharField(max_length=24,default='purchased'); expiry=models.DateTimeField(null=True,blank=True); created_at=models.DateTimeField(auto_now_add=True); updated_at=models.DateTimeField(auto_now=True)
    class Meta: ordering=['-created_at']; indexes=[models.Index(fields=['contract_id','status'])]
